import { z } from 'zod';
import crypto from 'crypto';
import { GoogleGenerativeAI } from '@google/generative-ai';
import { logger } from './utils/logger';
import { rateLimiter } from './middleware/rateLimiter';
import { requireAuth } from './middleware/auths';

// Initialize Express Router
const router = Router();

// Initialize Gemini Client
const genAI = new GoogleGenerativeAI(process.env.GEMINI_API_KEY || 'MOCK_GEMINI_KEY');

// PCI-DSS Compliant In-Memory Database and Advanced Metrics State Stores for dCVV2 Enrollments
interface EnrolledCard {
  panHash: string;
  maskedPan: string;
  expiry: string;
  refreshInterval: number; // in seconds
  derivationKey: string; // Hex-encoded card-specific key
  enrolledAt: Date;
  status: 'ACTIVE' | 'SUSPENDED' | 'LOCKED' | 'PENDING_VERIFICATION';
  lastGeneratedAt?: Date;
  generationCount: number;
  riskProfile: 'LOW' | 'MEDIUM' | 'HIGH';
  failedAttempts: number;
  metadata?: Record<string, unknown>;
}

interface DCVV2AuditLog {
  eventId: string;
  timestamp: Date;
  panHash: string;
  action: 'ENROLL' | 'UNENROLL' | 'GENERATE' | 'CHALLENGE' | 'SUSPEND' | 'INQUIRY';
  ipAddress: string;
  userAgent: string;
  riskScore: number;
  decision: string;
  success: boolean;
}

interface SystemConfigStore {
  maintenanceMode: boolean;
  globalMaxGenerationLimitPerMinute: number;
  enforceStrictMfa: boolean;
  geminiModelVersion: string;
}

const enrolledCardsDb = new Map<string, EnrolledCard>();
const auditLogStore: DCVV2AuditLog[] = [];
const systemConfig: SystemConfigStore = {
  maintenanceMode: false,
  globalMaxGenerationLimitPerMinute: 1000,
  enforceStrictMfa: false,
  geminiModelVersion: 'gemini-1.5-flash',
};

// Pre-seed a test card for instant verification/demo purposes
const SEED_PAN = '4111111111111111';
const SEED_PAN_HASH = crypto.createHash('sha256').update(SEED_PAN).digest('hex');
enrolledCardsDb.set(SEED_PAN_HASH, {
  panHash: SEED_PAN_HASH,
  maskedPan: '411111******1111',
  expiry: '12/29',
  refreshInterval: 60, // 1 minute refresh for demo
  derivationKey: crypto.randomBytes(32).toString('hex'),
  enrolledAt: new Date(),
  status: 'ACTIVE',
  generationCount: 0,
  riskProfile: 'LOW',
  failedAttempts: 0,
  metadata: { seeded: true, tier: 'ENTERPRISE' },
});

// Helper: Mask PAN for logging and response payloads
function maskPan(pan: string): string {
  if (!pan || pan.length < 10) return '****';
  return `${pan.substring(0, 6)}******${pan.substring(pan.length - 4)}`;
}

// Helper: Generate SHA-256 hash of PAN for secure lookups
function hashPan(pan: string): string {
  return crypto.createHash('sha256').update(pan).digest('hex');
}

// Helper: Generate Dynamic CVV2 using HMAC-SHA256 with time-step sliding windows
function generateDynamicCVV2(pan: string, expiry: string, derivationKey: string, interval: number): { dcvv2: string; validUntil: Date; timeStep: number } {
  const now = Date.now();
  const timeStep = Math.floor(now / (interval * 1000));
  const message = `${pan}-${expiry}-${timeStep}`;
  
  const hmac = crypto.createHmac('sha256', Buffer.from(derivationKey, 'hex'));
  hmac.update(message);
  const hash = hmac.digest('hex');

  // Dynamic Truncation: Extract a 3-digit code from the hash
  const decimalValue = parseInt(hash.substring(0, 8), 16);
  const dcvv2Val = decimalValue % 1000;
  const dcvv2 = dcvv2Val.toString().padStart(3, '0');

  const validUntil = new Date((timeStep + 1) * interval * 1000);
  return { dcvv2, validUntil, timeStep };
}

// Helper: Gemini-Powered Security Risk Assessment with granular telemetry
async function analyzeSecurityRisk(
  maskedPan: string,
  ip: string,
  userAgent: string,
  context?: Record<string, any>
): Promise<{ riskScore: number; decision: 'APPROVE' | 'CHALLENGE' | 'DECLINE'; reason: string }> {
  if (systemConfig.maintenanceMode) {
    return {
      riskScore: 0,
      decision: 'APPROVE',
      reason: 'System is currently running in diagnostic maintenance mode.'
    };
  }

  if (!process.env.GEMINI_API_KEY || process.env.GEMINI_API_KEY === 'MOCK_GEMINI_KEY') {
    // Fallback rule-based engine if Gemini is not configured
    const isLocalhost = ip === '127.0.0.1' || ip === '::1' || ip === '::ffff:127.0.0.1';
    const riskScore = isLocalhost ? 5 : 25;
    return {
      riskScore,
      decision: riskScore > 70 ? 'DECLINE' : riskScore > 40 ? 'CHALLENGE' : 'APPROVE',
      reason: 'Rule-based fallback assessment (Gemini API key not configured).'
    };
  }

  try {
    const model = genAI.getGenerativeModel({ model: systemConfig.geminiModelVersion });
    const prompt = `
      You are an elite Visa Enterprise Security AI analyzing a request for Dynamic CVV2 (dCVV2) generation.
      Analyze the following request metadata for potential fraud, card-testing attacks, account takeover, or automated botting:
      - Masked PAN: ${maskedPan}
      - Request IP: ${ip}
      - User Agent: ${userAgent}
      - Transaction Context: ${JSON.stringify(context || {})}

      Respond strictly with a valid JSON object containing:
      {
        "riskScore": number (0 to 100 integer),
        "decision": "APPROVE" | "CHALLENGE" | "DECLINE",
        "reason": "string detailing precise security heuristics"
      }
    `;

    const result = await model.generateContent(prompt);
    const responseText = result.response.text().trim();
    const cleanJson = responseText.replace(/```json|```/g, '').trim();
    const parsed = JSON.parse(cleanJson);
    return {
      riskScore: typeof parsed.riskScore === 'number' ? parsed.riskScore : 15,
      decision: ['APPROVE', 'CHALLENGE', 'DECLINE'].includes(parsed.decision) ? parsed.decision : 'APPROVE',
      reason: parsed.reason || 'Successfully evaluated by Gemini Security Mesh.'
    };
  } catch (error) {
    logger.error('Gemini security check failed, falling back to rule engine:', error);
    return {
      riskScore: 10,
      decision: 'APPROVE',
      reason: 'Security check fallback due to upstream model timeout or network error.'
    };
  }
}

