import React, { useState, useEffect, useCallback } from 'react';
import axios from 'axios';

// ==========================================
// SECTION 1: TypeScript Interfaces & Types
// ==========================================

export interface VisaDCVV2CardProps {
  initialPan?: string;
  initialExpiry?: string;
  apiEndpoint?: string;
  authToken: string;
}

export interface EnrollmentState {
  enrolled: boolean;
  status: 'ACTIVE' | 'SUSPENDED' | 'NOT_ENROLLED';
  maskedPan: string;
  refreshInterval: number;
  generationCount: number;
  lastGeneratedAt?: string;
}

export interface DCVV2GenerationResult {
  dcvv2: string;
  validUntil: string;
  refreshInterval: number;
  maskedPan: string;
  securityAssessment: {
    riskScore: number;
    decision: 'APPROVE' | 'CHALLENGE' | 'DECLINE';
    reason: string;
  };
}

// ==========================================
// SECTION 2: React Hook Handlers (Custom Hook)
// ==========================================

export function useVisaDCVV2(authToken: string, baseUrl: string = '/api/visa-dcvv2') {
  const [loading, setLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [enrollment, setEnrollment] = useState<EnrollmentState | null>(null);
  const [dcvv2Data, setDcvv2Data] = useState<DCVV2GenerationResult | null>(null);
  const [countdown, setCountdown] = useState<number>(0);

  const headers = {
    Authorization: `Bearer ${authToken}`,
    'Content-Type': 'application/json',
  };

  const checkInquiry = useCallback(async (pan: string) => {
    if (!pan || pan.length < 13) return;
    setLoading(true);
    setError(null);
    try {
      const response = await axios.get(`${baseUrl}/inquiry/${pan}`, { headers });
      setEnrollment(response.data);
    } catch (err: any) {
      setError(err.response?.data?.error || 'Failed to check card enrollment status');
    } finally {
      setLoading(false);
    }
  }, [baseUrl, authToken]);

  const enrollCard = async (pan: string, expiry: string, cvv2: string, refreshInterval: number = 3600) => {
    setLoading(true);
    setError(null);
    try {
      const response = await axios.post(`${baseUrl}/enroll`, { pan, expiry, cvv2, refreshInterval }, { headers });
      await checkInquiry(pan);
      return response.data;
    } catch (err: any) {
      setError(err.response?.data?.error || 'Failed to enroll card');
      throw err;
    } finally {
      setLoading(false);
    }
  };

  const unenrollCard = async (pan: string) => {
    setLoading(true);
    setError(null);
    try {
      const response = await axios.post(`${baseUrl}/unenroll`, { pan }, { headers });
      setEnrollment(null);
      setDcvv2Data(null);
      return response.data;
    } catch (err: any) {
      setError(err.response?.data?.error || 'Failed to unenroll card');
      throw err;
    } finally {
      setLoading(false);
    }
  };

  const generateDCVV2 = async (pan: string, expiry: string, context?: any) => {
    setLoading(true);
    setError(null);
    try {
      const response = await axios.post(`${baseUrl}/generate`, { pan, expiry, context }, { headers });
      setDcvv2Data(response.data);
      if (response.data.validUntil) {
        const remaining = Math.floor((new Date(response.data.validUntil).getTime() - Date.now()) / 1000);
        setCountdown(remaining > 0 ? remaining : 0);
      }
      return response.data;
    } catch (err: any) {
      setError(err.response?.data?.error || 'Failed to generate dCVV2');
      throw err;
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    let timer: NodeJS.Timeout;
    if (countdown > 0) {
      timer = setInterval(() => {
        setCountdown((prev) => (prev > 1 ? prev - 1 : 0));
      }, 1000);
    }
    return () => clearInterval(timer);
  }, [countdown]);

  return {
    loading,
    error,
    enrollment,
    dcvv2Data,
    countdown,
    checkInquiry,
    enrollCard,
    unenrollCard,
    generateDCVV2,
  };
}

